<?php
require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';require_once __DIR__.'/backend/csrf.php';requireCustomer();$uid=(int)$_SESSION['user_id'];$s=$conn->prepare('SELECT u.*,t.full_name technician_name FROM users u LEFT JOIN technicians t ON t.id=u.preferred_technician_id WHERE u.id=?');$s->bind_param('i',$uid);$s->execute();$user=$s->get_result()->fetch_assoc();$techs=$conn->query("SELECT id,full_name,specialization FROM technicians WHERE status='active' ORDER BY full_name");$ids=$conn->prepare('SELECT provider FROM auth_identities WHERE user_id=? ORDER BY provider');$ids->bind_param('i',$uid);$ids->execute();$providers=array_column($ids->get_result()->fetch_all(MYSQLI_ASSOC),'provider');
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Account | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"></head><body><header class="navbar"><div class="logo">Oh My Gracious</div><nav><a href="user-dashboard.php">Dashboard</a><a href="booking.php">Book</a><a href="booking-history.php">History</a><a href="saved-designs.php">Saved Designs</a><a class="active" href="account.php">My Account</a><a href="logout.php" class="logout-btn">Logout</a></nav></header><main class="page-wrap narrow"><div class="page-heading"><div><p class="eyebrow">USER ACCOUNT</p><h1>My Profile & Security</h1><p>Keep your contact details and salon preferences accurate.</p></div></div><?php if(isset($_GET['saved'])):?><div class="alert success">Profile updated.</div><?php endif;?><?php if(isset($_GET['password'])):?><div class="alert success">Password changed.</div><?php endif;?><?php if(!empty($_GET['error'])):?><div class="alert error"><?=h((string)$_GET['error'])?></div><?php endif;?>
<section class="panel"><h2>Personal Information</h2><form action="backend/update-account.php" method="POST" class="form-grid two"><?=csrfInput()?><div class="field span-2"><label>Full Name</label><input name="full_name" value="<?=h($user['full_name'])?>" required></div><div class="field"><label>Email</label><input value="<?=h($user['email'])?>" readonly><small><?= $user['email_verified_at']?'✓ Verified':'Not verified'?></small></div><div class="field"><label>Phone Number</label><input name="phone_number" value="<?=h($user['phone_number'])?>" required><small><?= $user['phone_verified_at']?'✓ Verified':'Not verified'?></small></div><div class="field"><label>Date of Birth</label><input type="date" name="date_of_birth" value="<?=h($user['date_of_birth'])?>"></div><div class="field"><label>Preferred Technician</label><select name="preferred_technician_id"><option value="">No preference</option><?php while($t=$techs->fetch_assoc()):?><option value="<?= (int)$t['id']?>" <?= (int)$user['preferred_technician_id']===(int)$t['id']?'selected':''?>><?=h($t['full_name'].' — '.$t['specialization'])?></option><?php endwhile;?></select></div><div class="field span-2"><label>Nail Preferences</label><textarea name="nail_preferences" rows="3"><?=h($user['nail_preferences'])?></textarea></div><div class="field span-2"><label>Allergies / Sensitivities</label><textarea name="allergy_notes" rows="3"><?=h($user['allergy_notes'])?></textarea><small>Visible only to authorized salon staff for service safety.</small></div><div class="span-2"><button class="btn primary" type="submit">Save Profile</button></div></form></section>
<section class="panel"><h2>Connected Login Methods</h2><div class="chip-row"><?php foreach(['password','google','facebook','phone'] as $p):?><span class="chip <?=in_array($p,$providers,true)?'good':''?>"><?=in_array($p,$providers,true)?'✓ ':'○ '?><?=h(ucfirst($p))?></span><?php endforeach;?></div></section>
<?php if(in_array('password',$providers,true)):?><section class="panel"><h2>Change Password</h2><form action="backend/change-password.php" method="POST" class="form-grid two"><?=csrfInput()?><div class="field span-2"><label>Current Password</label><input type="password" name="current_password" required></div><div class="field"><label>New Password</label><input type="password" name="new_password" required></div><div class="field"><label>Confirm New Password</label><input type="password" name="confirm_password" required></div><div class="span-2"><button class="btn primary">Change Password</button></div></form></section><?php endif;?></main></body></html>
